-- Schema of database 'hh_water' (PostgreSQL 16), generated by Hibernate from the JPA entities.
-- Reference only: the services create/update these tables automatically (spring.jpa.hibernate.ddl-auto=update).

CREATE TABLE public.corrective_actions (
    id bigint NOT NULL,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    action_type character varying(25) NOT NULL,
    assigned_to character varying(255),
    completed_date date,
    cost double precision,
    description character varying(1000) NOT NULL,
    issue_id bigint NOT NULL,
    issue_number character varying(255),
    outcome character varying(1000),
    planned_date date,
    status character varying(15),
    village character varying(255),
    CONSTRAINT corrective_actions_action_type_check CHECK (((action_type)::text = ANY ((ARRAY['CHLORINATION'::character varying, 'SOURCE_DISINFECTION'::character varying, 'PIPELINE_REPAIR'::character varying, 'HANDPUMP_REPAIR'::character varying, 'FLUSHING'::character varying, 'ALTERNATE_SUPPLY'::character varying, 'SOURCE_CLOSURE'::character varying, 'FOGGING'::character varying, 'LARVICIDE'::character varying, 'AWARENESS_DRIVE'::character varying, 'ORS_DISTRIBUTION'::character varying, 'MEDICAL_CAMP'::character varying, 'OTHER'::character varying])::text[]))),
    CONSTRAINT corrective_actions_status_check CHECK (((status)::text = ANY ((ARRAY['PLANNED'::character varying, 'IN_PROGRESS'::character varying, 'COMPLETED'::character varying, 'CANCELLED'::character varying])::text[])))
);
ALTER TABLE public.corrective_actions ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.corrective_actions_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
CREATE TABLE public.public_health_issues (
    id bigint NOT NULL,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    affected_population integer,
    assigned_to character varying(255),
    category character varying(30) NOT NULL,
    description character varying(1000),
    issue_number character varying(20),
    reported_by character varying(255),
    reported_date date,
    resolution_notes character varying(1000),
    resolved_date date,
    severity character varying(10),
    source character varying(15),
    source_id bigint,
    source_name character varying(255),
    status character varying(15),
    suspected_cases integer,
    title character varying(255) NOT NULL,
    village character varying(255) NOT NULL,
    CONSTRAINT public_health_issues_category_check CHECK (((category)::text = ANY ((ARRAY['WATER_CONTAMINATION'::character varying, 'SUPPLY_DISRUPTION'::character varying, 'PIPELINE_LEAKAGE'::character varying, 'STAGNANT_WATER'::character varying, 'MOSQUITO_BREEDING'::character varying, 'WATERBORNE_DISEASE_CLUSTER'::character varying, 'OPEN_DEFECATION'::character varying, 'SOLID_WASTE'::character varying, 'OTHER'::character varying])::text[]))),
    CONSTRAINT public_health_issues_severity_check CHECK (((severity)::text = ANY ((ARRAY['LOW'::character varying, 'MEDIUM'::character varying, 'HIGH'::character varying, 'CRITICAL'::character varying])::text[]))),
    CONSTRAINT public_health_issues_source_check CHECK (((source)::text = ANY ((ARRAY['MANUAL'::character varying, 'QUALITY_TEST'::character varying, 'FIELD_REPORT'::character varying, 'SURVEILLANCE'::character varying])::text[]))),
    CONSTRAINT public_health_issues_status_check CHECK (((status)::text = ANY ((ARRAY['OPEN'::character varying, 'INVESTIGATING'::character varying, 'ACTION_TAKEN'::character varying, 'RESOLVED'::character varying, 'CLOSED'::character varying])::text[])))
);
ALTER TABLE public.public_health_issues ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.public_health_issues_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
CREATE TABLE public.water_quality_tests (
    id bigint NOT NULL,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    arsenic double precision,
    coliform_present boolean,
    ecoli_present boolean,
    findings character varying(1000),
    fluoride double precision,
    iron double precision,
    issue_id bigint,
    method character varying(20),
    nitrate double precision,
    overall_status character varying(10),
    ph double precision,
    remarks character varying(500),
    residual_chlorine double precision,
    source_id bigint NOT NULL,
    source_name character varying(255),
    tds double precision,
    test_date date,
    tested_by character varying(255),
    turbidity double precision,
    village character varying(255),
    CONSTRAINT water_quality_tests_method_check CHECK (((method)::text = ANY ((ARRAY['FIELD_TEST_KIT'::character varying, 'H2S_VIAL'::character varying, 'LABORATORY'::character varying])::text[]))),
    CONSTRAINT water_quality_tests_overall_status_check CHECK (((overall_status)::text = ANY ((ARRAY['SAFE'::character varying, 'MARGINAL'::character varying, 'UNSAFE'::character varying, 'UNTESTED'::character varying])::text[])))
);
ALTER TABLE public.water_quality_tests ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.water_quality_tests_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
CREATE TABLE public.water_sources (
    id bigint NOT NULL,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    daily_capacity_litres double precision,
    households_served integer,
    landmark character varying(255),
    last_chlorinated_date date,
    last_quality_status character varying(10),
    last_tested_date date,
    latitude double precision,
    longitude double precision,
    managed_by character varying(255),
    name character varying(255) NOT NULL,
    population_served integer,
    source_code character varying(20),
    status character varying(25),
    supply_hours_per_day double precision,
    supply_schedule character varying(255),
    type character varying(20) NOT NULL,
    village character varying(255) NOT NULL,
    ward character varying(255),
    CONSTRAINT water_sources_last_quality_status_check CHECK (((last_quality_status)::text = ANY ((ARRAY['SAFE'::character varying, 'MARGINAL'::character varying, 'UNSAFE'::character varying, 'UNTESTED'::character varying])::text[]))),
    CONSTRAINT water_sources_status_check CHECK (((status)::text = ANY ((ARRAY['FUNCTIONAL'::character varying, 'PARTIALLY_FUNCTIONAL'::character varying, 'NON_FUNCTIONAL'::character varying, 'CONTAMINATED'::character varying])::text[]))),
    CONSTRAINT water_sources_type_check CHECK (((type)::text = ANY ((ARRAY['HANDPUMP'::character varying, 'BOREWELL'::character varying, 'OPEN_WELL'::character varying, 'PIPED_SUPPLY'::character varying, 'OVERHEAD_TANK'::character varying, 'POND'::character varying, 'RIVER'::character varying, 'RO_PLANT'::character varying, 'TANKER'::character varying])::text[])))
);
ALTER TABLE public.water_sources ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
